# Extract foreground coordinates from the shown demo motif manually; 4-connected comps
rows=[(9,[5]),(10,[4,6,7,8]),(11,[7,9]),(12,[5,6,7,8]),(13,[6])]
pts={(r,c) for r,cs in rows for c in cs}
while pts:
 p=pts.pop(); comp={p}; q=[p]
 while q:
  r,c=q.pop()
  for z in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
   if z in pts: pts.remove(z);comp.add(z);q.append(z)
 print(len(comp), sorted(comp))
